/**
 * The Node half of the dice-core roll contract: every vector in
 * golden/rolls.json (browser-generated by `npm run goldens:update`, see
 * scripts/verify-headless-parity.mjs) must settle to the same faces, tick
 * count and final state in Node — on the SIMD build and on the scalar one.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { defaultPublicDir, fsAssetSource, rollHeadless } from 'dice-core/node';
import type { WorldFixture } from 'dice-core/wasm/WorldRecorder';
import { WASM_SCALAR_DIR, WASM_SIMD_DIR } from 'dice-core/wasm/wasmArtifact';

interface GoldenVector {
    expr: string;
    seed: number;
    faces: number[];
    opposedFaces?: number[];
    fixedTicks: number;
    stateHash: string;
}

interface GoldenFile {
    schema: number;
    solverRevision: number;
    world: string;
    vectors: GoldenVector[];
}

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const readJson = <T>(rel: string): T =>
    JSON.parse(readFileSync(path.join(PACKAGE_ROOT, rel), 'utf8')) as T;

const golden = readJson<GoldenFile>('golden/rolls.json');
const world = readJson<WorldFixture>(golden.world);
const buildInfo = JSON.parse(
    readFileSync(path.join(defaultPublicDir(), 'wasm/build-info.json'), 'utf8')
) as { solver_revision: number };

describe('dice-core roll goldens', () => {
    it('cover every die shape, rerolls, explosions and opposed rolls', () => {
        expect(golden.schema).toBe(1);
        expect(golden.vectors.length).toBeGreaterThanOrEqual(40);
        const exprs = golden.vectors.map((v) => v.expr).join(' ');
        for (const shape of [
            'd4',
            'd6',
            'd8',
            'd10',
            'd12',
            'd20',
            'd100',
            'dF',
            'r1',
            '!',
            ' vs ',
        ]) {
            expect(exprs, shape).toContain(shape);
        }
    });

    it('were generated by this solver revision', () => {
        // A solver change moves every vector: regenerate, review the diff, commit.
        expect(
            golden.solverRevision,
            'golden/rolls.json is from another solver revision — run `npm run goldens:update`'
        ).toBe(buildInfo.solver_revision);
    });

    const assets = fsAssetSource();
    describe.each([WASM_SIMD_DIR, WASM_SCALAR_DIR])('%s build', (preferredDir) => {
        it.each(golden.vectors.map((v) => [`${v.expr} seed ${v.seed}`, v] as const))(
            '%s',
            async (_label, want) => {
                const r = await rollHeadless(want.expr, want.seed, null, {
                    assets,
                    world,
                    preferredDir,
                });
                expect(r.trace.faceValues).toEqual(want.faces);
                expect(r.trace.opposedFaceValues).toEqual(want.opposedFaces);
                expect(r.trace.fixedTicks).toBe(want.fixedTicks);
                expect(r.trace.stateHash).toBe(want.stateHash);
            }
        );
    });
});
